import{At as e,Pt as t,Ut as n,gt as r,ht as i,mt as a,n as o,pt as s,ut as c}from"./chunks/framework.BrKcMR_c.js";var l=JSON.parse(`{"title":"ADR-0025: Progressive single-flight startup","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/0025-progressive-single-flight-startup.md","filePath":"adrs/0025-progressive-single-flight-startup.md","lastUpdated":1789092097000}`),u={name:`adrs/0025-progressive-single-flight-startup.md`};function d(o,l,u,d,f,p){let m=t(`Term`);return e(),s(`div`,null,[l[22]||=a(`<h1 id="adr-0025-progressive-single-flight-startup" tabindex="-1">ADR-0025: Progressive single-flight startup <a class="header-anchor" href="#adr-0025-progressive-single-flight-startup" aria-label="Permalink to “ADR-0025: Progressive single-flight startup”">​</a></h1><p><strong>Status:</strong> Accepted · 2026-08-31 · Extends <a href="/adrs/0002-ui-architecture">ADR-0002</a>, <a href="/adrs/0003-persistence-grdb">ADR-0003</a>, <a href="/adrs/0006-mcp-integration">ADR-0006</a>, <a href="/adrs/0009-goat-home-and-mcp-config">ADR-0009</a>, and <a href="/adrs/0024-deterministic-prompt-budgeting">ADR-0024</a></p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2>`,3),c(`p`,null,[l[2]||=c(`code`,null,`AppModel.shared`,-1),l[3]||=i(` is created before the first window. Its initializer previously read and migrated the engine file, read credentials, opened SQLite, ran every database migration, and sealed incomplete messages after a crash. `,-1),l[4]||=c(`code`,null,`ContentView.task`,-1),l[5]||=i(` then ran theme and `,-1),r(m,{term:`pen`},{default:n(()=>[...l[0]||=[i(`Pen`,-1)]]),_:1}),l[6]||=i(` file work, restored chats, probed the engine and selected model, and finally loaded every enabled `,-1),r(m,{term:`mcp`},{default:n(()=>[...l[1]||=[i(`MCP server`,-1)]]),_:1}),l[7]||=i(` in one serial chain.`,-1)]),l[23]||=c(`p`,null,`This made filesystem or database latency part of time to first frame. An unavailable engine or slow MCP server also delayed restored chat selection and the first genuinely empty state. Multiple windows could start the same sequence again, and cancellation of one view-owned task could interrupt shared application initialization. During restoration, the UI presented empty arrays as real emptiness and accepted New Chat or configuration mutations which a later snapshot assignment could overwrite.`,-1),c(`p`,null,[l[9]||=i(`MCP added another head-of-line delay. Enabled servers connected one at a time, even though they have independent processes, transports, `,-1),r(m,{term:`tool`},{default:n(()=>[...l[8]||=[i(`tools`,-1)]]),_:1}),l[10]||=i(`, and failure outcomes.`,-1)]),l[24]||=a(`<h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><h3 id="keep-the-composition-root-initializer-cheap" tabindex="-1">Keep the composition-root initializer cheap <a class="header-anchor" href="#keep-the-composition-root-initializer-cheap" aria-label="Permalink to “Keep the composition-root initializer cheap”">​</a></h3><p><code>AppModel.init</code> reads only small <code>UserDefaults</code> presentation values and creates service objects with inert fallback configuration. It performs no GOAT Home file reads, credential reads, database open, migration, recovery, theme scan, Pen scan, engine request, or MCP process launch.</p><p>Local bootstrap runs from an app-owned task after the first SwiftUI surface exists. A detached local loader opens and validates <code>GoatDatabase</code>, performs crash recovery and legacy migrations, reads engine and theme files, and returns Sendable records and specifications. Observable <code>ChatSession</code> and <code>Pen</code> objects are created only when that snapshot is atomically published on <code>MainActor</code>.</p>`,4),c(`p`,null,[l[12]||=i(`This loader is the first bounded off-main file boundary. Step 4 generalizes the boundary to the remaining `,-1),r(m,{term:`shepherd`},{default:n(()=>[...l[11]||=[i(`Shepherd`,-1)]]),_:1}),l[13]||=i(`, attachment, Pen, theme, and view file work.`,-1)]),l[25]||=c(`h3`,{id:`one-startup-operation-for-the-application`,tabindex:`-1`},[i(`One startup operation for the application `),c(`a`,{class:`header-anchor`,href:`#one-startup-operation-for-the-application`,"aria-label":`Permalink to “One startup operation for the application”`},`​`)],-1),l[26]||=c(`p`,null,[c(`code`,null,`StartupCoordinator`),i(` retains one unstructured startup task. Every window and every repeated `),c(`code`,null,`start()`),i(` caller awaits that same task. Cancelling a view waiter does not cancel application initialization. A completed startup is not repeated.`)],-1),l[27]||=c(`p`,null,`Startup exposes these observable phases:`,-1),c(`ol`,null,[l[18]||=c(`li`,null,[c(`code`,null,`launching`),i(`: the lightweight composition root exists.`)],-1),l[19]||=c(`li`,null,[c(`code`,null,`restoringLocalState`),i(`: database and GOAT Home state are loading away from `),c(`code`,null,`MainActor`),i(`.`)],-1),c(`li`,null,[l[15]||=c(`code`,null,`connectingServices`,-1),l[16]||=i(`: chats, Pens, `,-1),r(m,{term:`theme`},{default:n(()=>[...l[14]||=[i(`themes`,-1)]]),_:1}),l[17]||=i(`, engine profiles, and selection are available while the engine and MCP attempts settle.`,-1)]),l[20]||=c(`li`,null,[c(`code`,null,`ready`),i(`: the initial engine and MCP attempts have both reached a terminal outcome. Ready does not mean every optional service is healthy.`)],-1),l[21]||=c(`li`,null,[c(`code`,null,`failed`),i(`: durable local state could not be established. The user gets the error and an explicit Retry action.`)],-1)]),l[28]||=a(`<p>The coordinator can be reset only by that explicit failed-startup Retry path. A retry cannot race user mutations because persistent mutation remains gated while local state is unavailable.</p><h3 id="local-state-is-the-first-interactive-boundary" tabindex="-1">Local state is the first interactive boundary <a class="header-anchor" href="#local-state-is-the-first-interactive-boundary" aria-label="Permalink to “Local state is the first interactive boundary”">​</a></h3><p>The sidebar and detail pane show a restoring surface until the database-backed local snapshot is published. They never interpret initial empty arrays as an empty pasture. New Chat, New Pen, Settings configuration, drag, rename, and other persistent mutations remain unavailable until that publication.</p><p>If a successful snapshot contains no chats, GOAT first inserts one chat durably, then publishes and selects it. A database open, read, or initial insert failure does not silently enter a lossy in-memory mode. Startup moves to <code>failed</code> and offers Retry.</p><p>Restored selection and lazy transcript loading begin before service connection finishes. Transcript loading has separate loading, failed, and Retry presentation, so a failed read is not an indefinitely blank chat.</p><p>The one-time database-project to Pen migration checks every legacy project ID on every needed run and creates only missing Pen folders. A partial prior migration no longer prevents the remaining projects from being recovered.</p><p>If a chat points to a Pen which was not materialized, the chat appears in the loose Chats section instead of disappearing from every sidebar group. Distinguishing missing files from unreadable or malformed engine, Pen, theme, credential, and MCP stores, plus fail-closed recovery and atomic write rules, belongs to the Step 5 persistence decision. Moving those reads does not declare their existing parsers validated.</p><h3 id="services-settle-concurrently-and-do-not-own-local-usability" tabindex="-1">Services settle concurrently and do not own local usability <a class="header-anchor" href="#services-settle-concurrently-and-do-not-own-local-usability" aria-label="Permalink to “Services settle concurrently and do not own local usability”">​</a></h3><p>After local publication, engine discovery, selected-model capability probing, and MCP startup begin concurrently. Chat history, local navigation, and persistent CRUD stay usable while they run. Send depends on its direct requirements: durable local state, loaded transcript, healthy settled engine/model capability, and a free app-wide turn slot. It does not wait for an unrelated MCP server to finish connecting.</p><p>MCP first reconciles and publishes every configured server as disconnected or connecting. Enabled servers without a retained client then connect concurrently. The app mirrors each terminal result as it arrives, so one slow or failed server does not prevent another server from becoming visible and usable. <code>ready</code> waits for all initial attempts to settle, but the rest of the app is already progressive.</p><p>Operation ownership, truly hard MCP deadlines, process cleanup, and stale reload rejection remain required by Step 5. This ADR removes serial startup dependency without claiming those security properties early.</p><h3 id="measure-locally" tabindex="-1">Measure locally <a class="header-anchor" href="#measure-locally" aria-label="Permalink to “Measure locally”">​</a></h3><p>Debug diagnostics use a monotonic clock and record local restore, engine connection, MCP connection, and total startup duration. These are local logs only. No telemetry or network reporting is added.</p><h3 id="required-tests" tabindex="-1">Required tests <a class="header-anchor" href="#required-tests" aria-label="Permalink to “Required tests”">​</a></h3><ul><li>Concurrent callers execute one startup operation, and later callers join its completed result.</li><li>Cancelling a view waiter does not cancel the retained startup task.</li><li>An explicit failed-startup reset permits one fresh attempt.</li><li>Phase readiness distinguishes local availability from service settlement and persistence failure.</li><li>Composer admission rejects unavailable local state independently of engine, transcript, and turn-busy state.</li><li>MCP reconciliation publishes all enabled pending servers as connecting before connection work and disabled servers as disconnected.</li></ul><p>The full verification suite remains the commit gate.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>The window can render before database migration or GOAT Home scanning completes.</li><li>Restored chats become browseable before engine and MCP startup settle, and a slow tool server no longer serializes every other server.</li><li>False empty states and snapshot-overwrite mutations are removed from startup.</li><li>Persistence failure is louder, but GOAT no longer invites the user to create unsaved work without consent.</li><li>The initial empty chat adds one awaited database insert before local publication. This small durability cost is intentional.</li><li>Startup has explicit state and additional tests instead of relying on array emptiness and engine health as indirect signals.</li><li>Some synchronous file entry points still exist after startup. Step 4 moves them behind worker boundaries, and Step 5 serializes and secures their persistence semantics.</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to “Alternatives considered”">​</a></h2><p>Keep eager initialization and add a splash screen (rejected: it hides blocking rather than removing it), detach the existing serial <code>start()</code> function wholesale (rejected: observable objects and UI publication belong on <code>MainActor</code>), allow ephemeral chat after database failure (rejected: silent data loss), wait for every service before exposing restored state (rejected: local data does not depend on localhost service health), connect MCP servers serially (rejected: independent failures create avoidable head-of-line latency), and cancel startup with its first view (rejected: application lifetime is not view lifetime).</p>`,20)])}var f=o(u,[[`render`,d]]);export{l as __pageData,f as default};